# -*- coding: utf-8 -*-
"""docs/4.3-风险表.docx —— 按 game-docs-and-sheets-inventory.md 4.3 写。

清单要求：风险清单（描述/概率/影响/等级/应对/信号）。
事实来源：3.1 的 6 条风险、3.4 的真机未测、2.3 的内容量（34/60）、3.2 的荣誉未接、4.2 的缓冲，
以及本会话真实发生过的事故（图片配额把 267 轮的会话卡死）。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "4.3-风险表.docx")


